//! Concrete owner RPC activities. Owner contracts remain generated by their bounded contexts.

use std::{collections::HashMap, time::Instant};

use async_trait::async_trait;
use gavel_auction::rpc as auction;
use gavel_notify::rpc as notify;
use gavel_payments_prost::gavel::payments::v1 as payments;
use tonic::{Code, Request};

use crate::{
    activities::{
        AttemptPaymentIntent, AuctionActivities, AuctionMutationOutcome, CloseAuctionIntent,
        ConfirmWinnerIntent, ExpirePaymentIntent, ForfeitCandidateIntent,
        NotificationAcknowledgement, NotificationKind, NotifyActivities, NotifyIntent,
        OutbidNotificationIntent, PaymentsActivities, RecoveryNotificationIntent,
        SettlementAttemptRead, SettlementAttemptSnapshot,
    },
    rpc_policy::{self, ActivityPolicy, FailureClass, Intent, IntentKey},
    workflows::{CandidateId, PaymentAttemptId, ProcessError, SettlementAttemptStatus},
};

type AuctionClient =
    auction::auction_service_client::AuctionServiceClient<tonic::transport::Channel>;
type PaymentsClient = gavel_payments_tonic::gavel::payments::v1::tonic::payments_service_client::PaymentsServiceClient<tonic_bsr::transport::Channel>;
type NotifyClient = notify::notify_service_client::NotifyServiceClient<tonic::transport::Channel>;

#[derive(Clone)]
pub struct OwnerRpcActivities {
    auction: AuctionClient,
    payments: PaymentsClient,
    notify: NotifyClient,
    auction_principal_id: String,
    workload_spiffe_id: Option<String>,
    policy: ActivityPolicy,
}

impl OwnerRpcActivities {
    pub fn new(
        auction: AuctionClient,
        payments: PaymentsClient,
        notify: NotifyClient,
        auction_principal_id: impl Into<String>,
    ) -> Self {
        Self {
            auction,
            payments,
            notify,
            auction_principal_id: auction_principal_id.into(),
            workload_spiffe_id: None,
            policy: ActivityPolicy::default(),
        }
    }

    pub fn new_authenticated(
        auction: AuctionClient,
        payments: PaymentsClient,
        notify: NotifyClient,
        auction_principal_id: impl Into<String>,
        workload_spiffe_id: impl Into<String>,
    ) -> Self {
        Self {
            auction,
            payments,
            notify,
            auction_principal_id: auction_principal_id.into(),
            workload_spiffe_id: Some(workload_spiffe_id.into()),
            policy: ActivityPolicy::default(),
        }
    }

    fn auction_request<T>(
        &self,
        message: T,
        correlation_id: &str,
        causation_id: &str,
    ) -> Result<Request<T>, ProcessError> {
        let mut request = Request::new(message);
        for (key, value) in [
            ("x-gavel-principal-type", "service_account"),
            ("x-gavel-principal-id", self.auction_principal_id.as_str()),
            ("x-correlation-id", correlation_id),
            ("x-causation-id", causation_id),
        ] {
            request
                .metadata_mut()
                .insert(key, value.parse().map_err(|_| ProcessError::InvalidInput)?);
        }
        if let Some(identity) = &self.workload_spiffe_id {
            request.metadata_mut().insert(
                "x-gavel-spiffe-id",
                identity.parse().map_err(|_| ProcessError::InvalidInput)?,
            );
        }
        request.set_timeout(self.policy.start_to_close_timeout);
        Ok(request)
    }

    fn payments_request<T>(&self, message: T) -> Result<tonic_bsr::Request<T>, ProcessError> {
        let mut request = tonic_bsr::Request::new(message);
        if let Some(identity) = &self.workload_spiffe_id {
            request.metadata_mut().insert(
                "x-gavel-spiffe-id",
                identity.parse().map_err(|_| ProcessError::InvalidInput)?,
            );
        }
        request.set_timeout(self.policy.start_to_close_timeout);
        Ok(request)
    }

    fn notify_request<T>(&self, message: T) -> Result<Request<T>, ProcessError> {
        let mut request = Request::new(message);
        if let Some(identity) = &self.workload_spiffe_id {
            request.metadata_mut().insert(
                "x-gavel-spiffe-id",
                identity.parse().map_err(|_| ProcessError::InvalidInput)?,
            );
        }
        request.set_timeout(self.policy.start_to_close_timeout);
        Ok(request)
    }

    async fn read_settlement_attempt(
        &self,
        read: &SettlementAttemptRead,
    ) -> Result<(SettlementAttemptSnapshot, Option<String>), ProcessError> {
        let message = payments::GetSettlementAttemptRequest {
            payment_attempt_id: read.attempt_id.as_str().to_owned(),
            expected_auction_id: read.expected_auction_id.as_str().to_owned(),
            expected_settlement_round: read.expected_round.get(),
            correlation_id: read.correlation_id.clone(),
            consistency_token: read.consistency_token.clone(),
        };
        let mut client = self.payments.clone();
        let started = Instant::now();
        let response = client
            .get_settlement_attempt(self.payments_request(message)?)
            .await;
        record_bsr_rpc("payments", "get_settlement_attempt", started, &response);
        let response = response.map_err(map_bsr_status)?.into_inner();
        let result = match response.outcome {
            Some(payments::get_settlement_attempt_response::Outcome::Result(result)) => result,
            Some(payments::get_settlement_attempt_response::Outcome::Rejection(rejection)) => {
                return Err(domain_rejection(rejection.reason));
            }
            None => return Err(ProcessError::InvariantViolation),
        };
        if result.payment_attempt_id != read.attempt_id.as_str()
            || result.auction_id != read.expected_auction_id.as_str()
            || result.settlement_round != read.expected_round.get()
        {
            return Err(ProcessError::InvariantViolation);
        }
        let candidate_id = CandidateId::parse(result.candidate_id)?;
        let (status, recovery_url) = payment_status(result.status, result.state_data)?;
        Ok((
            SettlementAttemptSnapshot {
                attempt_id: read.attempt_id.clone(),
                candidate_id,
                status,
                version: result.version,
                checked_at_token: result.checked_at_token,
            },
            recovery_url,
        ))
    }

    async fn send_notification(
        &self,
        intent: &NotifyIntent,
        recovery_url: Option<String>,
    ) -> Result<NotificationAcknowledgement, ProcessError> {
        let template = match intent.kind {
            NotificationKind::SettlementCandidate => {
                notify::NotificationTemplate::SettlementCandidate
            }
            NotificationKind::SettlementCandidateFailed => {
                notify::NotificationTemplate::SettlementCandidateFailed
            }
            NotificationKind::PaymentRecoveryRequired => {
                notify::NotificationTemplate::PaymentRecoveryRequired
            }
            NotificationKind::WinnerConfirmed => notify::NotificationTemplate::WinnerConfirmed,
        };
        let key_template = match intent.kind {
            NotificationKind::SettlementCandidate => rpc_policy::NotificationTemplate::Settlement,
            NotificationKind::SettlementCandidateFailed => {
                rpc_policy::NotificationTemplate::CandidateFailed
            }
            NotificationKind::PaymentRecoveryRequired => rpc_policy::NotificationTemplate::Recovery,
            NotificationKind::WinnerConfirmed => rpc_policy::NotificationTemplate::Winner,
        };
        let notification_id = IntentKey::for_auction(
            intent.auction_id.as_str(),
            Intent::Notify {
                template: key_template,
                round: intent.round.get(),
            },
        )
        .map_err(|_| ProcessError::InvalidInput)?
        .to_string();
        let mut data = HashMap::new();
        data.insert(
            "auction_id".to_owned(),
            intent.auction_id.as_str().to_owned(),
        );
        if let Some(url) = recovery_url {
            data.insert("recovery_url".to_owned(), url);
        }
        let message = notify::SendNotificationRequest {
            notification_id: notification_id.clone(),
            recipient_id: intent.recipient_id.as_str().to_owned(),
            template: template as i32,
            data,
            idempotency_key: notification_id.clone(),
            template_version: 1,
            correlation_id: intent.correlation_id.clone(),
        };
        let mut client = self.notify.clone();
        let started = Instant::now();
        let response = client
            .send_notification(self.notify_request(message)?)
            .await;
        record_rpc("notify", "send_notification", started, &response);
        let response = response.map_err(map_status)?.into_inner();
        match response.outcome {
            Some(notify::send_notification_response::Outcome::Accepted(_)) => {
                Ok(NotificationAcknowledgement {
                    notification_id,
                    accepted: true,
                })
            }
            Some(notify::send_notification_response::Outcome::Rejection(rejection)) => {
                Err(domain_rejection(rejection.reason))
            }
            None => Err(ProcessError::InvariantViolation),
        }
    }
}

#[async_trait]
impl AuctionActivities for OwnerRpcActivities {
    async fn close_auction(
        &self,
        intent: CloseAuctionIntent,
    ) -> Result<AuctionMutationOutcome, ProcessError> {
        let seconds = i64::try_from(intent.observed_at_millis / 1_000)
            .map_err(|_| ProcessError::InvalidInput)?;
        let nanos = i32::try_from((intent.observed_at_millis % 1_000) * 1_000_000)
            .map_err(|_| ProcessError::InvalidInput)?;
        let message = auction::CloseAuctionRequest {
            auction_id: intent.auction_id.to_string(),
            now: Some(prost_types::Timestamp { seconds, nanos }),
            idempotency_key: intent.idempotency_key,
        };
        let request = self.auction_request(
            message,
            &intent.call.correlation_id,
            &intent.call.causation_id,
        )?;
        let mut client = self.auction.clone();
        let started = Instant::now();
        let response = client.close_auction(request).await;
        record_rpc("auction", "close_auction", started, &response);
        let response = response.map_err(map_status)?.into_inner();
        match response.outcome {
            Some(auction::close_auction_response::Outcome::Closed(closed)) => {
                Ok(AuctionMutationOutcome {
                    version: closed.version,
                })
            }
            Some(auction::close_auction_response::Outcome::Rejection(rejection)) => {
                Err(domain_rejection(rejection.reason))
            }
            None => Err(ProcessError::InvariantViolation),
        }
    }

    async fn forfeit_settlement_candidate(
        &self,
        intent: ForfeitCandidateIntent,
    ) -> Result<AuctionMutationOutcome, ProcessError> {
        let message = auction::ForfeitSettlementCandidateRequest {
            auction_id: intent.auction_id.to_string(),
            candidate_id: intent.candidate_id.to_string(),
            settlement_round: intent.round.get(),
            idempotency_key: intent.idempotency_key,
        };
        let request = self.auction_request(
            message,
            &intent.call.correlation_id,
            &intent.call.causation_id,
        )?;
        let mut client = self.auction.clone();
        let started = Instant::now();
        let response = client.forfeit_settlement_candidate(request).await;
        record_rpc(
            "auction",
            "forfeit_settlement_candidate",
            started,
            &response,
        );
        let response = response.map_err(map_status)?.into_inner();
        match response.outcome {
            Some(auction::forfeit_settlement_candidate_response::Outcome::Advanced(value)) => {
                Ok(AuctionMutationOutcome {
                    version: value.version,
                })
            }
            Some(auction::forfeit_settlement_candidate_response::Outcome::Rejection(value)) => {
                Err(domain_rejection(value.reason))
            }
            None => Err(ProcessError::InvariantViolation),
        }
    }

    async fn confirm_winner(
        &self,
        intent: ConfirmWinnerIntent,
    ) -> Result<AuctionMutationOutcome, ProcessError> {
        let message = auction::ConfirmWinnerRequest {
            auction_id: intent.auction_id.to_string(),
            candidate_id: intent.candidate_id.to_string(),
            payment_id: intent.payment_id,
            idempotency_key: intent.idempotency_key,
        };
        let request = self.auction_request(
            message,
            &intent.call.correlation_id,
            &intent.call.causation_id,
        )?;
        let mut client = self.auction.clone();
        let started = Instant::now();
        let response = client.confirm_winner(request).await;
        record_rpc("auction", "confirm_winner", started, &response);
        let response = response.map_err(map_status)?.into_inner();
        match response.outcome {
            Some(auction::confirm_winner_response::Outcome::Confirmed(value)) => {
                Ok(AuctionMutationOutcome {
                    version: value.version,
                })
            }
            Some(auction::confirm_winner_response::Outcome::Rejection(value)) => {
                Err(domain_rejection(value.reason))
            }
            None => Err(ProcessError::InvariantViolation),
        }
    }
}

#[async_trait]
impl PaymentsActivities for OwnerRpcActivities {
    async fn attempt_payment(
        &self,
        intent: AttemptPaymentIntent,
    ) -> Result<SettlementAttemptSnapshot, ProcessError> {
        let correlation_id = intent.correlation_id.clone();
        let message = payments::AttemptPaymentRequest {
            auction_id: intent.auction_id.to_string(),
            settlement_round: intent.round.get(),
            candidate_id: intent.candidate_id.to_string(),
            amount: Some(payments::Money {
                minor_units: intent.amount.minor_units,
                currency_code: intent.amount.currency_code,
            }),
            idempotency_key: intent.idempotency_key,
            correlation_id: intent.correlation_id,
            consistency_token: intent.consistency_token,
        };
        let mut client = self.payments.clone();
        let started = Instant::now();
        let response = client
            .attempt_payment(self.payments_request(message)?)
            .await;
        record_bsr_rpc("payments", "attempt_payment", started, &response);
        let response = response.map_err(map_bsr_status)?.into_inner();
        let result = match response.outcome {
            Some(payments::attempt_payment_response::Outcome::Result(value)) => value,
            Some(payments::attempt_payment_response::Outcome::Rejection(value)) => {
                return Err(domain_rejection(value.reason));
            }
            None => return Err(ProcessError::InvariantViolation),
        };
        let attempt_id = PaymentAttemptId::parse(result.payment_attempt_id)?;
        if matches!(
            payments::PaymentAttemptStatus::try_from(result.status),
            Ok(payments::PaymentAttemptStatus::Succeeded)
        ) {
            return self
                .read_settlement_attempt(&SettlementAttemptRead {
                    attempt_id,
                    expected_auction_id: intent.auction_id,
                    expected_round: intent.round,
                    correlation_id,
                    consistency_token: result.checked_at_token,
                })
                .await
                .map(|(snapshot, _)| snapshot);
        }
        let (status, _) = payment_status_from_attempt(result.status, result.recovery_url)?;
        Ok(SettlementAttemptSnapshot {
            attempt_id,
            candidate_id: intent.candidate_id,
            status,
            version: result.version,
            checked_at_token: result.checked_at_token,
        })
    }

    async fn get_settlement_attempt(
        &self,
        read: SettlementAttemptRead,
    ) -> Result<SettlementAttemptSnapshot, ProcessError> {
        self.read_settlement_attempt(&read)
            .await
            .map(|(safe, _)| safe)
    }

    async fn expire_payment(
        &self,
        intent: ExpirePaymentIntent,
    ) -> Result<SettlementAttemptSnapshot, ProcessError> {
        let reconciliation = SettlementAttemptRead {
            attempt_id: intent.attempt_id.clone(),
            expected_auction_id: intent.auction_id.clone(),
            expected_round: intent.round,
            correlation_id: intent.correlation_id.clone(),
            consistency_token: intent.consistency_token.clone(),
        };
        let message = payments::ExpirePaymentRequest {
            payment_attempt_id: intent.attempt_id.to_string(),
            idempotency_key: intent.idempotency_key,
            correlation_id: intent.correlation_id,
            consistency_token: intent.consistency_token,
        };
        let mut client = self.payments.clone();
        let started = Instant::now();
        let response = client.expire_payment(self.payments_request(message)?).await;
        record_bsr_rpc("payments", "expire_payment", started, &response);
        let response = response.map_err(map_bsr_status)?.into_inner();
        let expired = match response.outcome {
            Some(payments::expire_payment_response::Outcome::Expired(value)) => value,
            Some(payments::expire_payment_response::Outcome::Rejection(value)) => {
                if payments::PaymentRejectionCode::try_from(value.code).ok()
                    == Some(payments::PaymentRejectionCode::AlreadySucceeded)
                {
                    let (snapshot, _) = self.read_settlement_attempt(&reconciliation).await?;
                    return matches!(snapshot.status, SettlementAttemptStatus::Succeeded { .. })
                        .then_some(snapshot)
                        .ok_or(ProcessError::InvariantViolation);
                }
                return Err(domain_rejection(value.reason));
            }
            None => return Err(ProcessError::InvariantViolation),
        };
        if expired.payment_attempt_id != intent.attempt_id.as_str() {
            return Err(ProcessError::InvariantViolation);
        }
        Ok(SettlementAttemptSnapshot {
            attempt_id: intent.attempt_id,
            candidate_id: intent.candidate_id,
            status: SettlementAttemptStatus::Expired,
            version: expired.version,
            checked_at_token: expired.checked_at_token,
        })
    }
}

#[async_trait]
impl NotifyActivities for OwnerRpcActivities {
    async fn notify(
        &self,
        intent: NotifyIntent,
    ) -> Result<NotificationAcknowledgement, ProcessError> {
        self.send_notification(&intent, None).await
    }

    async fn notify_payment_recovery(
        &self,
        intent: RecoveryNotificationIntent,
    ) -> Result<NotificationAcknowledgement, ProcessError> {
        let (snapshot, recovery_url) = self.read_settlement_attempt(&intent.attempt).await?;
        if snapshot.status != SettlementAttemptStatus::RecoveryRequired {
            return Err(ProcessError::OwnerRejected {
                code: "recovery_not_required".to_owned(),
            });
        }
        let recovery_url = recovery_url.ok_or(ProcessError::InvariantViolation)?;
        let notification = NotifyIntent {
            auction_id: intent.attempt.expected_auction_id,
            round: intent.attempt.expected_round,
            recipient_id: intent.recipient_id,
            kind: NotificationKind::PaymentRecoveryRequired,
            correlation_id: intent.attempt.correlation_id,
        };
        self.send_notification(&notification, Some(recovery_url))
            .await
    }

    async fn notify_outbid(
        &self,
        intent: OutbidNotificationIntent,
    ) -> Result<NotificationAcknowledgement, ProcessError> {
        if intent.aggregate_version == 0 {
            return Err(ProcessError::InvalidInput);
        }
        let notification_id = format!(
            "outbid/{}:{}",
            intent.auction_id.as_str(),
            intent.aggregate_version
        );
        let message = notify::SendNotificationRequest {
            notification_id: notification_id.clone(),
            recipient_id: intent.recipient_id.as_str().to_owned(),
            template: notify::NotificationTemplate::BidderOutbid as i32,
            data: HashMap::from([(
                "auction_id".to_owned(),
                intent.auction_id.as_str().to_owned(),
            )]),
            idempotency_key: notification_id.clone(),
            template_version: 1,
            correlation_id: intent.correlation_id,
        };
        let mut client = self.notify.clone();
        let started = Instant::now();
        let response = client
            .send_notification(self.notify_request(message)?)
            .await;
        record_rpc("notify", "send_notification", started, &response);
        let response = response.map_err(map_status)?.into_inner();
        match response.outcome {
            Some(notify::send_notification_response::Outcome::Accepted(_)) => {
                Ok(NotificationAcknowledgement {
                    notification_id,
                    accepted: true,
                })
            }
            Some(notify::send_notification_response::Outcome::Rejection(rejection)) => {
                Err(domain_rejection(rejection.reason))
            }
            None => Err(ProcessError::InvariantViolation),
        }
    }
}

fn payment_status(
    status: i32,
    data: Option<payments::settlement_attempt_result::StateData>,
) -> Result<(SettlementAttemptStatus, Option<String>), ProcessError> {
    use payments::settlement_attempt_result::StateData;
    match payments::PaymentAttemptStatus::try_from(status).ok() {
        Some(payments::PaymentAttemptStatus::Processing) if data.is_none() => {
            Ok((SettlementAttemptStatus::Processing, None))
        }
        Some(payments::PaymentAttemptStatus::RecoveryRequired) => match data {
            Some(StateData::RecoveryRequired(value)) if !value.recovery_url.is_empty() => Ok((
                SettlementAttemptStatus::RecoveryRequired,
                Some(value.recovery_url),
            )),
            _ => Err(ProcessError::InvariantViolation),
        },
        Some(payments::PaymentAttemptStatus::Succeeded) => match data {
            Some(StateData::Succeeded(value)) if !value.payment_id.is_empty() => Ok((
                SettlementAttemptStatus::Succeeded {
                    payment_id: value.payment_id,
                },
                None,
            )),
            _ => Err(ProcessError::InvariantViolation),
        },
        Some(payments::PaymentAttemptStatus::Expired) if data.is_none() => {
            Ok((SettlementAttemptStatus::Expired, None))
        }
        _ => Err(ProcessError::InvariantViolation),
    }
}

fn payment_status_from_attempt(
    status: i32,
    recovery_url: String,
) -> Result<(SettlementAttemptStatus, Option<String>), ProcessError> {
    match payments::PaymentAttemptStatus::try_from(status).ok() {
        Some(payments::PaymentAttemptStatus::Processing) if recovery_url.is_empty() => {
            Ok((SettlementAttemptStatus::Processing, None))
        }
        Some(payments::PaymentAttemptStatus::RecoveryRequired) if !recovery_url.is_empty() => Ok((
            SettlementAttemptStatus::RecoveryRequired,
            Some(recovery_url),
        )),
        Some(payments::PaymentAttemptStatus::Expired) if recovery_url.is_empty() => {
            Ok((SettlementAttemptStatus::Expired, None))
        }
        _ => Err(ProcessError::InvariantViolation),
    }
}

fn domain_rejection(reason: String) -> ProcessError {
    ProcessError::OwnerRejected {
        code: if reason.is_empty() {
            "owner_rejected".to_owned()
        } else {
            reason
        },
    }
}

fn map_status(status: tonic::Status) -> ProcessError {
    map_code(status.code())
}

fn record_rpc<T>(
    service: &'static str,
    method: &'static str,
    started: Instant,
    result: &Result<tonic::Response<T>, tonic::Status>,
) {
    record_rpc_metrics(
        service,
        method,
        result
            .as_ref()
            .err()
            .map_or("OK", |status| tonic_code(status.code())),
        started.elapsed(),
    );
}

fn record_bsr_rpc<T>(
    service: &'static str,
    method: &'static str,
    started: Instant,
    result: &Result<tonic_bsr::Response<T>, tonic_bsr::Status>,
) {
    record_rpc_metrics(
        service,
        method,
        result
            .as_ref()
            .err()
            .map_or("OK", |status| bsr_code(status.code())),
        started.elapsed(),
    );
}

fn record_rpc_metrics(
    service: &'static str,
    method: &'static str,
    grpc_code: &'static str,
    duration: std::time::Duration,
) {
    metrics::counter!(
        "gavel_rpc_client_requests_total",
        "service" => "processes",
        "rpc_service" => service,
        "rpc_method" => method,
        "grpc_code" => grpc_code
    )
    .increment(1);
    metrics::histogram!(
        "gavel_rpc_client_duration_seconds",
        "service" => "processes",
        "rpc_service" => service,
        "rpc_method" => method
    )
    .record(duration.as_secs_f64());
}

const fn tonic_code(code: tonic::Code) -> &'static str {
    match code {
        tonic::Code::Ok => "OK",
        tonic::Code::Cancelled => "CANCELLED",
        tonic::Code::Unknown => "UNKNOWN",
        tonic::Code::InvalidArgument => "INVALID_ARGUMENT",
        tonic::Code::DeadlineExceeded => "DEADLINE_EXCEEDED",
        tonic::Code::NotFound => "NOT_FOUND",
        tonic::Code::AlreadyExists => "ALREADY_EXISTS",
        tonic::Code::PermissionDenied => "PERMISSION_DENIED",
        tonic::Code::ResourceExhausted => "RESOURCE_EXHAUSTED",
        tonic::Code::FailedPrecondition => "FAILED_PRECONDITION",
        tonic::Code::Aborted => "ABORTED",
        tonic::Code::OutOfRange => "OUT_OF_RANGE",
        tonic::Code::Unimplemented => "UNIMPLEMENTED",
        tonic::Code::Internal => "INTERNAL",
        tonic::Code::Unavailable => "UNAVAILABLE",
        tonic::Code::DataLoss => "DATA_LOSS",
        tonic::Code::Unauthenticated => "UNAUTHENTICATED",
    }
}

const fn bsr_code(code: tonic_bsr::Code) -> &'static str {
    match code {
        tonic_bsr::Code::Ok => "OK",
        tonic_bsr::Code::Cancelled => "CANCELLED",
        tonic_bsr::Code::Unknown => "UNKNOWN",
        tonic_bsr::Code::InvalidArgument => "INVALID_ARGUMENT",
        tonic_bsr::Code::DeadlineExceeded => "DEADLINE_EXCEEDED",
        tonic_bsr::Code::NotFound => "NOT_FOUND",
        tonic_bsr::Code::AlreadyExists => "ALREADY_EXISTS",
        tonic_bsr::Code::PermissionDenied => "PERMISSION_DENIED",
        tonic_bsr::Code::ResourceExhausted => "RESOURCE_EXHAUSTED",
        tonic_bsr::Code::FailedPrecondition => "FAILED_PRECONDITION",
        tonic_bsr::Code::Aborted => "ABORTED",
        tonic_bsr::Code::OutOfRange => "OUT_OF_RANGE",
        tonic_bsr::Code::Unimplemented => "UNIMPLEMENTED",
        tonic_bsr::Code::Internal => "INTERNAL",
        tonic_bsr::Code::Unavailable => "UNAVAILABLE",
        tonic_bsr::Code::DataLoss => "DATA_LOSS",
        tonic_bsr::Code::Unauthenticated => "UNAUTHENTICATED",
    }
}
fn map_bsr_status(status: tonic_bsr::Status) -> ProcessError {
    use tonic_bsr::Code;
    match status.code() {
        Code::Unavailable | Code::ResourceExhausted | Code::DeadlineExceeded => {
            ProcessError::DependencyUnavailable
        }
        Code::InvalidArgument
        | Code::FailedPrecondition
        | Code::NotFound
        | Code::PermissionDenied => ProcessError::OwnerRejected {
            code: status.code().to_string(),
        },
        _ => ProcessError::InvariantViolation,
    }
}

fn map_code(code: Code) -> ProcessError {
    match rpc_policy::classify(code) {
        FailureClass::Retryable => ProcessError::DependencyUnavailable,
        FailureClass::ExpectedRejection => ProcessError::OwnerRejected {
            code: code.to_string(),
        },
        FailureClass::Fatal => ProcessError::InvariantViolation,
    }
}

pub fn temporal_activity_options() -> temporalio_sdk::ActivityOptions {
    let policy = ActivityPolicy::default();
    let retry = temporalio_common::RetryPolicy::builder()
        .initial_interval(policy.retry.initial_interval)
        .backoff_coefficient(f64::from(policy.retry.backoff_coefficient))
        .maximum_interval(policy.retry.maximum_interval)
        .maximum_attempts(policy.retry.maximum_attempts)
        .non_retryable_error_types(["OwnerRejected", "InvalidInput", "InvariantViolation"])
        .build();
    temporalio_sdk::ActivityOptions::with_start_to_close_timeout(policy.start_to_close_timeout)
        .retry_policy(retry)
        .build()
}

